/**
 * Base64-embedded BKC WeatherSys logo, used anywhere a synchronous data URL is
 * needed (jsPDF.addImage, ExcelJS workbook.addImage) instead of the imported
 * asset URL used by <img> tags (bkc-weathersys-logo.png). Kept as one small
 * generated file so the source PNG stays the single source of truth.
 */
export const BKC_LOGO_BASE64 = 'data:image/png;base64,';

export const BKC_LOGO_WIDTH = 188;
export const BKC_LOGO_HEIGHT = 109;
